async function(){const env='cloudbase-d8gwtxzm64150b7e0',out={state:'COMPLETED',environment:env,tests:[]};for(const [name,data,expected]of [['health',{action:'health'},null],['get-closed',{action:'get',payload:{storeId:'g1-catalog-store'}},'CONFIGURATION_REQUIRED'],['forged-payload',{action:'get',payload:{storeId:'g1-catalog-store',role:'admin'}},'INVALID_REQUEST'],['slots-closed',{action:'slots.list',payload:{storeId:'g1-catalog-store'}},'INVALID_REQUEST']]){try{const response=await wx.cloud.callFunction({name:'store',data,config:{env}}),r=response.result,code=r&&r.error&&r.error.code||null;out.tests.push({name,passed:expected?!!r&&!r.ok&&code===expected:!!r&&r.ok===true,ok:r&&r.ok===true,code,requestId:r&&r.requestId});}catch(e){out.tests.push({name,passed:false,transportCode:e.errCode||e.code||'TRANSPORT_ERROR'});}}const db=wx.cloud.database({env});for(const collection of ['stores','store_config']){try{await db.collection(collection).limit(1).get();out.tests.push({name:collection+'-client-read',passed:false,rejected:false});}catch(e){const code=e.errCode||e.code;out.tests.push({name:collection+'-client-read',passed:Number(code)===-502003,rejected:true,code});}}out.state=out.tests.every(row=>row.passed)?'PASSED':'PARTIAL';return out;}
